import{_ as t}from"./chunks/19e9c12ccbd9b8720c8d.CIRwMA24.js";import{_ as r,C as o,o as l,c as i,j as e,a as s,E as n,a6 as h}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"生活艰难，习惯就好（心智掌控之道）","description":"","frontmatter":{"title":"生活艰难，习惯就好（心智掌控之道）","originalTitle":"Life Is Hard, Get Used To It (The Way To Mental Mastery)","date":"2023-02-25","originalUrl":"https://thedankoe.com/letters/life-is-hard-get-used-to-it-the-way-to-mental-mastery/","minutes":10,"sourceHash":"5425ff3273b0106b49e0296882ad8e35e6bd3554d0f9cf290d28ea0e5c6872ee","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/life-is-hard-get-used-to-it-the-way-to-mental-mastery/"}]]},"headers":[],"relativePath":"letters/life-is-hard-get-used-to-it-the-way-to-mental-mastery.md","filePath":"letters/life-is-hard-get-used-to-it-the-way-to-mental-mastery.md"}'),d={name:"letters/life-is-hard-get-used-to-it-the-way-to-mental-mastery.md"};function m(c,p,u,f,b,_){const a=o("ArticleMeta");return l(),i("div",null,[p[0]||(p[0]=e("h1",{id:"生活艰难-习惯就好-心智掌控之道",tabindex:"-1"},[s("生活艰难，习惯就好（心智掌控之道） "),e("a",{class:"header-anchor",href:"#生活艰难-习惯就好-心智掌控之道","aria-label":'Permalink to "生活艰难，习惯就好（心智掌控之道）"'},"​")],-1)),n(a),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/aMZv0uoHMPI?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><em>舒适是一种无常的心境，但人类却喜欢把它称之为家。</em></p><p>有趣的是，我们在这个拒绝离开的心理小屋里把自己禁锢得越久，就会越觉得不舒服。</p><p>通往真正舒适的唯一途径是<em>达到一种能够坦然面对生活中不可避免的不适感的心境</em><em>。</em></p><p><strong>问题在于：</strong></p><p>当人们面对不适时，他们的本能反应是逃避，而不是战斗。</p><p>我们可能不会逃离物理上的处境，但我们会试图跑向过往经验带来的心理舒适区。即便我们的身体静止不动，我们的内心也想四处游走。</p><p>这就产生了张力（紧张感），除非这种张力得到化解，否则它停留的时间就会比预期的更长。</p><p><em>这个问题的结果就是分心、感到“迷茫”以及陷入墨守成规的死胡同。</em></p><p>我们不知道接下来该追求什么，因为我们缺乏那种随着时间的推移由不适感带来的清晰度。</p><p>当我们处于这种“迷茫”或混乱的心境时，是不可能看透最初的问题所在的。</p><p>为什么？因为它正迫切地祈求被解决。</p><p>心智决定了我们如何与现实互动。</p><p>心智蕴藏着视角，视角蕴藏着认知，认知蕴藏着行为。</p><p>从上到下，大多数人持有一种狭隘的视角，这导致他们对局势产生负面的认知，进而支配了他们盲目的行为。</p><p>我们的目标是充满艺术感和优雅地度过一生。</p><p>也就是说，无论心智想如何去解读局势的艰难，都要与当下融为一体。</p><p>当你：</p><ul><li>用开放的心态去对待生活，从而拓宽你的视角</li><li>获得接受现实局势的力量</li><li>收获进步带来的喜悦</li></ul><p>你就会意识到，你一直被一个谎言所蒙骗。</p><p>传统的道路并不是通往美好生活的道路。</p><p>为了做好这一点，有几件事你需要明白。</p><h2 id="_3个视角" tabindex="-1">3个视角 <a class="header-anchor" href="#_3个视角" aria-label="Permalink to &quot;3个视角&quot;">​</a></h2><p>期望与现实之间的落差会产生张力，从而导致痛苦。</p><p>我热爱哲学，但我很快意识到理论必须与实践相结合。</p><p>知识必须在不止一个方面与现实发生碰撞，才能检验其有效性。</p><p>哲学家可以整天进行理性思考，但他们能经营一家企业吗？</p><p>当他们损失了10万美元时，会有什么反应？</p><p>那么当你<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">开始创作内容</a>，获得了一个粉丝，却流失了五个呢？</p><p>他们能建立、维持并经营好一段人际关系吗？</p><p>还是他们只是在猜测如何建立良好的人际关系，并将其作为“最佳路径”推销给那些向他们学习的人？</p><p>当他们的狗死去了呢？当他们的父母离世了呢？</p><p>言行必须一致。</p><p>一个超重的健康专家显然是很难让人信任的，但任何人都可以躲在匿名的网络个人资料后面。</p><p>最好的哲学是扎根于现实的哲学，而且这是因人而异的。</p><p>我想提供3个视角，以帮助你认识到缩小期望与现实之间、概念与经验之间、以及事实与非事实之间落差的重要性。</p><h3 id="期望-vs-现实" tabindex="-1">期望 VS 现实 <a class="header-anchor" href="#期望-vs-现实" aria-label="Permalink to &quot;期望 VS 现实&quot;">​</a></h3><p>期望就是信念，而我们的信念往往是无意识的，并在我们经历生活的过程中被条件反射般地植入我们的心智之中。</p><p>期望是对未来的一种投射。</p><p>它是一种假设，认为某事“应该”或“将会”发生。</p><p>西方的孩子经常被告知他们“应该”成为医生、工程师，或者获得其他某个高薪的职位。</p><p>孩子们被告知周日“将会”去教堂，而他们也就信了。</p><p>期望将你的心智局限在一个可预测的未来，并阻碍我们敞开心扉去迎接潜在的诸多未来。</p><p>在这种思想狭隘的状态下，我们的视角是受限的。</p><p>既然视角受限，我们对局势的认知自然也会受限。</p><p>带着不准确的认知，我们经常会做出无助于实现理想未来的选择。</p><p>选择很重要，它们一砖一瓦地建造着你的未来。</p><p>让我们来看看炎热天气和桑拿浴的例子。</p><p>当人们想到要在炎热的天气里出门时，他们会抱怨，因为他们的期望将他们的心智局限在了一个负面的结果上。</p><p>当人们想到要去蒸桑拿时，那是蓄意为之的。通常是为了实现一个有意义的结果。</p><p>这两种情况下的现实是一样的，但期望不同，正是这导致了前一种情况下的痛苦。</p><p>在一个更具现实意义的场景中，让我们来看看一个身负很多重担却想创业的人。</p><ul><li>他们看到那些没多少负担的人在炫耀自己6到12个月内的商业成功。</li><li>他们在没有结合自身处境背景的情况下，把那种期望装进了你的脑子里。</li><li>他们开始概念化地去想为什么自己做不到，并抱怨生活如何不公（因为他们有工作、有孩子、有配偶）。</li></ul><p>他们无法面对现实。</p><p>现实情况是，他们没有在自己责任较轻的时候抓住创业的机会，但这也没关系。已经无法改变了，你越早接受现实的本来面目，就能越早开始取得进步。</p><p>因为一旦他们确实接受了现实，他们就能用一种新的视角去接近那个目标——一种更可持续的视角。</p><p>他们可以去寻找契合的导师、教育以及策略，这些同样能带来成功，只是时间跨度更长一些。</p><p>唯一的另一个选择就是成为你期望的奴隶，永远无法达成那个目标，在生活中明明知道那是可能的，却只会抱怨你无法取得同样的成就。</p><h3 id="概念-vs-经验" tabindex="-1">概念 VS 经验 <a class="header-anchor" href="#概念-vs-经验" aria-label="Permalink to &quot;概念 VS 经验&quot;">​</a></h3><p>概念只能从经验中产生。</p><p>对此最大的误解的典型例子就是上帝、宇宙，或者任何你想用来称呼那种更高力量的词汇。</p><p>宗教人士执着于上帝的概念，却没能意识到这其实是一种经验。这个概念仅仅是那种经验的象征性表达。</p><p>两者的区别在于知道（knowing）与理解（understanding）。</p><p>概念让你知道，而经验让你理解。</p><p>知识是凌驾于现实之上的一层外衣，而理解是人类意识中固有的层面。</p><p>一个是向外的构建，另一个则是向内的真相。</p><p>概念是一种必须与现实碰撞才能被体验的指南。</p><p>现实就是经验，如果你稍微留心就会发现，一切不过如此。</p><p>人们喜欢概念化，因为这样他们就不必在这个世界上为了解决（内在和外在的）问题而向前迈进，去获得那些不那么肤浅、较少情绪化反应的经验。</p><h3 id="事实-vs-非事实" tabindex="-1">事实 VS 非事实 <a class="header-anchor" href="#事实-vs-非事实" aria-label="Permalink to &quot;事实 VS 非事实&quot;">​</a></h3><p>“事实就是如此（It is what it is）”是你一生中能听到的最深刻的话，但很少有人能意识到它背后的深度。</p><p>区分“事实”与“非事实”是缩小期望与现实之间，以及概念与经验之间落差的绝佳方法。</p><p>当下这一刻，就在你面前的事物，就是“事实”。</p><p>你手里杠铃的重量造成的困难是现实。期望它应该很轻松，则非现实。</p><p>努力闯出名堂的挣扎是经验。你脑海中那种充实的生活方式的概念则并非经验。</p><p>如果你想开启这段通往长期成功的旅程，请报名参加<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学大师班。</a></p><p>现在，我并不是说期望、概念和“非事实”就一定是不好的。</p><p>最大的问题在于负面的期望，在于那些自以为“全知”并阻碍你采取行动的概念，以及无法与“事实”融为一体的无能为力。</p><h3 id="重点在于" tabindex="-1">重点在于 <a class="header-anchor" href="#重点在于" aria-label="Permalink to &quot;重点在于&quot;">​</a></h3><p>综合所有这些视角，重点就在于：</p><p>当生活变得艰难、令人难以招架，或者你对自己的未来感到那种可怕的绝望感时，期望与现实之间就出现了失调。</p><p>你脑子里的信念、想法或思想，与正在你面前展开的当下不相匹配。</p><p>因为你给了它们太多的关注，它们就喧宾夺主，掩盖了你的感官认知。</p><p>换句话说，哪怕你<em>不想</em>去打扫房间，你依然可以去打扫，而且可以打扫得很干净。</p><p>你完全可以把“打扫房间”替换成任何一项活动。</p><h2 id="心智层次" tabindex="-1">心智层次 <a class="header-anchor" href="#心智层次" aria-label="Permalink to &quot;心智层次&quot;">​</a></h2><blockquote><p>任何问题都无法在制造它的同一意识层面上得到解决。——阿尔伯特·爱因斯坦</p></blockquote><p>问题是被编码在系统之中的，很少有人能看清它们的真面目。</p><p>问题正是引发期望与现实之间差距的导火索，只有当你能够弥合这一差距时，解决那个问题才会变得毫不费力。</p><p>但是，为了解决那个问题并弥合那一差距，你必须达到一个新的心智层次。</p><p>我们将“心智”定义为你与现实互动的方式。</p><p>从这个意义上说，心智就是视角。</p><p>把视角想象成一个领域，它容纳了所有的期望、信念、想法、技能、经验、潜能以及其他一切。</p><p>这个视角变得越宽广，你的心智层次就越高，你也越难死死抱住某一个期望、信念、技能等等不放。</p><p>随着你解决的每一个问题，感知到的生活难度都会下降，而你的心智层次则会提升。</p><p>你所面临的问题的难度，是你处于个人发展哪个阶段的首要指标。</p><p>而你能够解决的问题难度，就是你能为他人解决的问题难度。</p><p>也就是说，你越是通过迎接不断升级的挑战来发展自己，你获得的经验就越多。</p><p>你面临的挑战将需要你无数次地弥合期望与现实之间的差距，而你每一次这样做，都会获得一次教训和启示。</p><p>这种经验可以转移到商业中，因为产品就是用来解决问题的，所以你的经验越丰富，你的企业就越赚钱。</p><p>这其中必须有一种平衡，因为当你连每天走1万步的习惯都无法坚持时，你是不可能去尝试攀登珠穆朗玛峰的。</p><h2 id="活在你的边缘地带——心智掌控之道" tabindex="-1">活在你的边缘地带——心智掌控之道 <a class="header-anchor" href="#活在你的边缘地带——心智掌控之道" aria-label="Permalink to &quot;活在你的边缘地带——心智掌控之道&quot;">​</a></h2><blockquote><p>当你敞开心扉，生活在你的边缘地带时，你内心最深处的目标将慢慢开始显现。与此同时，你将体验到一层又一层的目标，每一层都越来越接近你最深层目标的圆满。——大卫·戴伊达（David Deida）</p></blockquote><p>要想达到新的心智层次，你必须得遇到问题。</p><p>你不能无所事事、虚度光阴，日复一日地做着同样的事情而不顾个人的进化。</p><p>你必须生活在技能与挑战的边缘地带。</p><p>随着你不断解决问题，你就会提升自己的心智层次。</p><p>为了解决问题，你必须提高你的技能水平。</p><h3 id="_1-追求一个有挑战性的目标" tabindex="-1">1) 追求一个有挑战性的目标 <a class="header-anchor" href="#_1-追求一个有挑战性的目标" aria-label="Permalink to &quot;1) 追求一个有挑战性的目标&quot;">​</a></h3><p>几乎我每一期的电子报都会提到这个道理。</p><p>你需要一个让你<em>每。一。天。</em>都在为之努力的目标。</p><p>一个能将你引向理想未来的目标，哪怕你还不知道那个未来是什么样子。</p><p>我可以假设它包括一个健康的身体、充裕的银行账户以及蓬勃发展的人际关系（内心的平静是追求这些目标的副产品，而不一定是实现它们的结果）。</p><p>这个目标终将被实现，而为了防止再次陷入随后的墨守成规的死胡同并从中挣脱出来，你将不得不设定一个新的目标（可能在一段时间内还不太清晰）。</p><h3 id="_2-对当下的困难保持觉察" tabindex="-1">2) 对当下的困难保持觉察 <a class="header-anchor" href="#_2-对当下的困难保持觉察" aria-label="Permalink to &quot;2) 对当下的困难保持觉察&quot;">​</a></h3><p>你把哪些评判、内涵和词汇与“挣扎”、“困难”或“艰难”这些词联系在一起？</p><p>它们是否会引发你对充满压力的未来的强迫性思考？</p><p>也许它们会勾起你对过去某个错误的记忆……一个让你恐惧到无法行动的错误？</p><p>又或者两者皆有，让你陷入焦虑的漩涡中？</p><p>再次强调，这些不过是你脑海中抱有的期望、概念，以及那些“并不存在的事物”。</p><p>它们不是现实，而现实本就包含挣扎、困难和艰难。你无法逃避它们。而这需要你对当下这一刻进行彻底的接纳。</p><h3 id="_3-触及感知阈值的临界点" tabindex="-1">3) 触及感知阈值的临界点 <a class="header-anchor" href="#_3-触及感知阈值的临界点" aria-label="Permalink to &quot;3) 触及感知阈值的临界点&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>如果你遇到了写作瓶颈……</p><p>如果你的5公里跑已经进行了30分钟……</p><p>如果你正在做365磅深蹲的最后一次重复……</p><p>如果你正犹豫要不要发布你的第一条内容……</p><p>如果你已经冥想了45分钟，而你的大脑正哀求你去查看一下手机通知……</p><p>各种想法和情绪会涌入你的脑海，而“唯一的出路就是穿过它”。</p><p>你必须<em>训练</em>你的疼痛耐受力，因为当你坚持足够长的时间，在任何情况下都能达到“跑步者高潮”时，奇迹就会发生。</p><p><strong>感知阈值</strong>是一段挣扎期之后的临界点，在这一点上，<em>由于你对局势的感知方式发生了转变，曾经困难的事情变得毫不费力。</em></p><p><em>期望坍缩为现实。</em></p><p><em>概念坍缩为体验。</em></p><p><em>“不存在的事物”坍缩为“存在的事物”。</em></p><p>这可能需要5分钟，也可能需要1小时，而对于那些无法立刻解决的问题，可能需要几年。</p><p>混乱是清晰的前提，而清晰是这个世界上最强效的燃料。</p><h3 id="_4-达到心智的新高度" tabindex="-1">4) 达到心智的新高度 <a class="header-anchor" href="#_4-达到心智的新高度" aria-label="Permalink to &quot;4) 达到心智的新高度&quot;">​</a></h3><p>跨越感知阈值会迫使你拉远视角，进入更高层级的心智，或者说，超越你原本狭隘的状态，获得更全局的视角。</p><p>从这个层级，你可以准确地感知你之前的问题，并看清它的本质。</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">写作时“没有灵感”变成了一个愚蠢的借口。</a></p><p>不做那最后一次带来最大收益的重复动作——会变成“我真是个小婊*砸，给我撑过去。”</p><p>不发布你的第一条内容会变成：“如果我不这么做，这就会变成习惯，我将一辈子困在现在的处境里，这跟我想要的完全相反。”</p><p>结果就是深深的满足感。</p><p>– Dan</p><p><strong>本周动态</strong></p><p>我只有一件事要告诉你。</p><p>Modern Mastery 2.0 已经发布，且正在持续建设中。</p><p>更少臃肿，更少负担，更多价值，更多个性化帮助。</p><p>在现有的200多篇文章和培训的基础上，我们将增加更多课程，致力于成为未来工作的教育平台。</p><p>YouTube课程、设计、剪辑、视觉构图、营销、产品构建，以及你可能会用到的一切。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">如果你感兴趣，读者可以在这里花5美元加入。</a></p><hr><p><a href="/en/letters/life-is-hard-get-used-to-it-the-way-to-mental-mastery">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',153))])}const y=r(d,[["render",m]]);export{g as __pageData,y as default};
